import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Extension Catalog","description":"Available plugins and how to install them","frontmatter":{"title":"Extension Catalog","description":"Available plugins and how to install them"},"headers":[],"relativePath":"engine/extension_catalog.md","filePath":"engine/extension_catalog.md","lastUpdated":1788476353000}'),o={name:"engine/extension_catalog.md"};function i(s,e,d,l,c,h){return r(),a("div",null,e[0]||(e[0]=[n(`<h1 id="extension-catalog" tabindex="-1">Extension Catalog <a class="header-anchor" href="#extension-catalog" aria-label="Permalink to &quot;Extension Catalog&quot;">​</a></h1><p>OIE is built around a modular extension model. Most of what looks like core functionality is in fact an extension: connectors, data types, filter and transformer steps, attachment viewers, and transmission modes are all loaded the same way a third-party plugin is.</p><p>Extensions are discovered at runtime. One install therefore serves both the desktop <a href="./desktop_administrator.html">Desktop Administrator</a> and the <a href="./web_administrator.html">Web Administrator</a>, with no separate web build to maintain and no way for a plugin to drift out of step with the engine it sits on.</p><p>Installing, enabling, disabling, and removing extensions is covered in the <a href="./plugins.html">Plugin Guide</a>.</p><h2 id="bundled-extensions" tabindex="-1">Bundled extensions <a class="header-anchor" href="#bundled-extensions" aria-label="Permalink to &quot;Bundled extensions&quot;">​</a></h2><p>OIE ships with 40 extensions in <code>OIE_HOME/extensions/</code>.</p><h3 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><code>dicom</code></td><td>DICOM Listener and Sender</td></tr><tr><td><code>doc</code></td><td>Document Writer, producing RTF or PDF from an HTML template. PDFs can be password protected</td></tr><tr><td><code>file</code></td><td>File Reader and Writer, covering local paths, FTP, SFTP, Amazon S3, SMB, and WebDAV</td></tr><tr><td><code>http</code></td><td>HTTP Listener and Sender</td></tr><tr><td><code>jdbc</code></td><td>Database Reader and Writer, using Insert, Update, or JavaScript statements</td></tr><tr><td><code>jms</code></td><td>JMS Listener and Sender</td></tr><tr><td><code>js</code></td><td>JavaScript Reader and Writer, for connecting to an arbitrary endpoint in code</td></tr><tr><td><code>smtp</code></td><td>SMTP Sender, with a template for building the message body</td></tr><tr><td><code>tcp</code></td><td>TCP Listener and Sender</td></tr><tr><td><code>vm</code></td><td>Channel Reader and Writer, for routing between channels in the same instance</td></tr><tr><td><code>ws</code></td><td>Web Service (SOAP) Listener and Sender</td></tr></tbody></table><h3 id="data-types" tabindex="-1">Data types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Extension</th><th>Format</th></tr></thead><tbody><tr><td><code>datatype-delimited</code></td><td>Delimited text (CSV, TSV, custom)</td></tr><tr><td><code>datatype-dicom</code></td><td>DICOM</td></tr><tr><td><code>datatype-edi</code></td><td>EDI / X12</td></tr><tr><td><code>datatype-hl7v2</code></td><td>HL7 v2.x</td></tr><tr><td><code>datatype-hl7v3</code></td><td>HL7 v3.x / CDA</td></tr><tr><td><code>datatype-json</code></td><td>JSON</td></tr><tr><td><code>datatype-ncpdp</code></td><td>NCPDP</td></tr><tr><td><code>datatype-raw</code></td><td>Raw (unstructured)</td></tr><tr><td><code>datatype-xml</code></td><td>XML</td></tr></tbody></table><h3 id="filter-and-transformer-steps" tabindex="-1">Filter and transformer steps <a class="header-anchor" href="#filter-and-transformer-steps" aria-label="Permalink to &quot;Filter and transformer steps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><code>destinationsetfilter</code></td><td>Destination Set Filter step, for excluding destinations from the source transformer</td></tr><tr><td><code>javascriptrule</code></td><td>JavaScript filter rule</td></tr><tr><td><code>javascriptstep</code></td><td>JavaScript transformer step</td></tr><tr><td><code>mapper</code></td><td>Mapper transformer step</td></tr><tr><td><code>messagebuilder</code></td><td>Message Builder transformer step</td></tr><tr><td><code>rulebuilder</code></td><td>Rule Builder filter rule</td></tr><tr><td><code>scriptfilerule</code></td><td>External Script filter rule</td></tr><tr><td><code>scriptfilestep</code></td><td>External Script transformer step</td></tr><tr><td><code>xsltstep</code></td><td>XSLT transformer step</td></tr></tbody></table><h3 id="viewers" tabindex="-1">Viewers <a class="header-anchor" href="#viewers" aria-label="Permalink to &quot;Viewers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><code>dicomviewer</code></td><td>DICOM attachment viewing in the message browser</td></tr><tr><td><code>imageviewer</code></td><td>Image attachment viewing in the message browser</td></tr><tr><td><code>pdfviewer</code></td><td>PDF attachment viewing in the message browser</td></tr><tr><td><code>textviewer</code></td><td>Text and RTF attachment viewing in the message browser</td></tr></tbody></table><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><code>dashboardstatus</code></td><td>Real-time connector status column on the Dashboard</td></tr><tr><td><code>datapruner</code></td><td>Automated message data pruning</td></tr><tr><td><code>directoryresource</code></td><td>Use a directory as a source of libraries to include in channels</td></tr><tr><td><code>globalmapviewer</code></td><td>View the global map and global channel maps in the Administrator</td></tr><tr><td><code>httpauth</code></td><td>Authentication providers for HTTP-based source connectors</td></tr><tr><td><code>serverlog</code></td><td>Real-time server log viewer in the Administrator</td></tr></tbody></table><h3 id="transmission-modes" tabindex="-1">Transmission modes <a class="header-anchor" href="#transmission-modes" aria-label="Permalink to &quot;Transmission modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><code>mllpmode</code></td><td>MLLP framing for socket and serial connectors</td></tr></tbody></table><h2 id="extension-directory-structure" tabindex="-1">Extension directory structure <a class="header-anchor" href="#extension-directory-structure" aria-label="Permalink to &quot;Extension directory structure&quot;">​</a></h2><p>Each extension lives in its own subdirectory under <code>OIE_HOME/extensions/</code>. Connectors describe themselves with <code>source.xml</code> and <code>destination.xml</code>, while plugins and data types use <code>plugin.xml</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extensions/</span></span>
<span class="line"><span>├── http/                         # Connector example</span></span>
<span class="line"><span>│   ├── http-server.jar           # Server-side classes</span></span>
<span class="line"><span>│   ├── http-client.jar           # Client-side classes (downloaded to the Administrator)</span></span>
<span class="line"><span>│   ├── http-shared.jar           # Shared classes</span></span>
<span class="line"><span>│   ├── source.xml                # Source connector metadata</span></span>
<span class="line"><span>│   └── destination.xml           # Destination connector metadata</span></span>
<span class="line"><span>└── datapruner/                   # Plugin example</span></span>
<span class="line"><span>    ├── datapruner-server.jar</span></span>
<span class="line"><span>    ├── datapruner-client.jar</span></span>
<span class="line"><span>    ├── datapruner-shared.jar</span></span>
<span class="line"><span>    └── plugin.xml                # Plugin metadata descriptor</span></span></code></pre></div><p>Some extensions also carry a <code>lib/</code> or <code>libs/</code> subdirectory for third-party dependencies. Client-only extensions, such as the Mapper and Rule Builder steps, ship no server jar at all.</p><h2 id="extension-metadata" tabindex="-1">Extension metadata <a class="header-anchor" href="#extension-metadata" aria-label="Permalink to &quot;Extension metadata&quot;">​</a></h2><p>A metadata descriptor declares:</p><ul><li>Extension name, author, and version</li><li>Server-side and client-side class names</li><li>Library JAR paths and their type (server, client, or shared)</li><li>API provider classes, meaning servlet interfaces and their implementations</li></ul><h2 id="community-plugins" tabindex="-1">Community plugins <a class="header-anchor" href="#community-plugins" aria-label="Permalink to &quot;Community plugins&quot;">​</a></h2><p>None of the following ship with OIE. Each is installed separately, and each is open source. Several add a tab or panel to both administrators from a single install, because extensions are discovered at runtime rather than built into a particular client.</p><p>The current catalog is maintained at <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">openintegrationengine.org/plugins</a>.</p><h3 id="web-support" tabindex="-1">Web Support <a class="header-anchor" href="#web-support" aria-label="Permalink to &quot;Web Support&quot;">​</a></h3><p>Installs the <a href="./web_administrator.html">Web Administrator</a> into the engine&#39;s embedded web server, along with the server-side APIs it uses for message serialization, JavaScript validation, and serving other plugins&#39; web interfaces.</p><p>Requires OIE 4.6.0. MPL 2.0. <a href="https://github.com/gibson9583/oie-web-support-plugin" target="_blank" rel="noreferrer">gibson9583/oie-web-support-plugin</a></p><h3 id="role-based-access-control" tabindex="-1">Role Based Access Control <a class="header-anchor" href="#role-based-access-control" aria-label="Permalink to &quot;Role Based Access Control&quot;">​</a></h3><p>Replaces the engine&#39;s default always-allow authorization controller with roles you define. Each role carries per-permission grants and can be restricted to specific channels, so a role only sees and operates on the channels it is meant to. Enforcement is server-side, meaning a denied operation fails at the server regardless of which client asked and regardless of what the UI chose to hide.</p><p>On first startup it creates its own <code>rbac_*</code> tables and seeds an admin role assigned to the initial admin user. Ships role management and task gating for both administrators in one zip; the web half is inert on servers that do not run the Web Administrator.</p><p>Requires OIE 4.6.0. MPL 2.0. <a href="https://github.com/diridium-com/role-based-access-control" target="_blank" rel="noreferrer">diridium-com/role-based-access-control</a></p><h3 id="oie-sentinel" tabindex="-1">OIE Sentinel <a class="header-anchor" href="#oie-sentinel" aria-label="Permalink to &quot;OIE Sentinel&quot;">​</a></h3><p>Monitoring and alerting for channel activity. Monitors are scoped to a channel, a channel group, a channel tag, or everything, with group and tag membership resolved live so reorganising channels does not mean revisiting monitors.</p><p>Seven monitor types: inactivity, low volume, anomaly against a rolling baseline, connection status, error rate (with a minimum-volume guard so one error on a quiet channel is not reported as 100%), queue depth, and channel state.</p><p>When a monitor breaches, Sentinel opens a problem, dispatches its actions, and tracks the problem until it clears or somebody resolves it. Delivery is by email, channel (VM Router), AWS SNS, or webhook, with per-monitor severity, a consecutive-breach threshold, storm control, escalation chains, and dependency suppression so a parent monitor silences its dependents on the same channel.</p><p>Runs in the Web Administrator only. There is no Swing client and no separate web application; it loads inside the console on the existing session.</p><p>Requires OIE 4.6.0. MPL 2.0. <a href="https://github.com/gibson9583/oie-sentinel" target="_blank" rel="noreferrer">gibson9583/oie-sentinel</a></p><h3 id="channel-and-code-template-history" tabindex="-1">Channel and Code Template History <a class="header-anchor" href="#channel-and-code-template-history" aria-label="Permalink to &quot;Channel and Code Template History&quot;">​</a></h3><p>Captures a version snapshot every time a channel or code template is saved, stored in the OIE database so history travels with ordinary database backups. No external Git server is involved.</p><p>Diffs are decomposed: a navigable tree lets you drill into individual scripts, connectors, filter and transformer steps, and plugin properties, with a side-by-side viewer showing word-level inline highlighting. Any version can be reverted to from a right-click, older versions can be pruned, and deleting a channel or code template writes a final snapshot so it can still be recovered.</p><p>Supports PostgreSQL, MySQL, Oracle, SQL Server, and Derby. Requires OIE 4.5.2 or later and Java 17. MPL 2.0. <a href="https://github.com/diridium-com/simple-channel-history" target="_blank" rel="noreferrer">diridium-com/simple-channel-history</a></p><h3 id="tls-manager" tabindex="-1">TLS Manager <a class="header-anchor" href="#tls-manager" aria-label="Permalink to &quot;TLS Manager&quot;">​</a></h3><p>Certificate management for OIE, available both in the Administrator and from the browser. Inspect the Java trust store, add trusted certificates, and manage local key pairs, with search, validity dates, and fingerprints. The browser-based certificate manager is served at <code>https://&lt;host&gt;:8443/tls-manager/</code>.</p><p><a href="https://github.com/NovaMap-Health/tls-manager-plugin" target="_blank" rel="noreferrer">NovaMap-Health/tls-manager-plugin</a></p><h3 id="cache-manager" tabindex="-1">Cache Manager <a class="header-anchor" href="#cache-manager" aria-label="Permalink to &quot;Cache Manager&quot;">​</a></h3><p>In-memory key-value lookups against external databases. The first call for a key queries the database; every call after that is served from memory. Built on Guava&#39;s <code>LoadingCache</code> with HikariCP connection pooling to avoid connection storms under load, with lazy per-key loading and eviction driven by a configurable maximum size and TTL.</p><p>Caches are defined in an admin UI, then called from a channel in one line. A cache inspector reports hit rates, memory use, and entry counts, and lets you browse what is currently cached. Database credentials are encrypted at rest using OIE&#39;s own encryptor, and activity is written to OIE&#39;s event system. A full REST API is included.</p><p>MPL 2.0. <a href="https://github.com/diridium-com/oie-cache-manager" target="_blank" rel="noreferrer">diridium-com/oie-cache-manager</a></p><h3 id="source-code-search" tabindex="-1">Source Code Search <a class="header-anchor" href="#source-code-search" aria-label="Permalink to &quot;Source Code Search&quot;">​</a></h3><p>Grep-style search across channel scripts, code templates, global scripts, and message templates, run from the Administrator. Literal or regex, case-sensitive or not, with scope control per artifact type and per channel, hierarchical results with location breadcrumbs and match highlighting, and export to JSON or CSV. The dialog is non-modal, so it stays open while you work.</p><p>MPL 2.0. <a href="https://github.com/diridium-com/oie-source-code-search" target="_blank" rel="noreferrer">diridium-com/oie-source-code-search</a></p><h3 id="thread-viewer" tabindex="-1">Thread Viewer <a class="header-anchor" href="#thread-viewer" aria-label="Permalink to &quot;Thread Viewer&quot;">​</a></h3><p>A dashboard tab showing live JVM thread activity: state, CPU time, and blocked and waited counts for every thread, with the full stack trace for whichever one is selected. Threads are classified by category (channel processing, database pool, HTTP/servlet, system/JVM, and others) and, where OIE&#39;s thread naming permits, correlated back to the channel and connector running them, which turns &quot;the engine is busy&quot; into a named channel.</p><p>Includes deadlock detection via <code>ThreadMXBean.findDeadlockedThreads()</code>, filtering by text, channel, category, or thread state, and jstack-compatible thread dump export. Contention tracking is only enabled while monitoring runs, and the last snapshot stays browsable after monitoring stops. Access is restricted to administrators through OIE&#39;s extension permission system.</p><p>Requires OIE 4.6.0. MIT. <a href="https://github.com/gibson9583/engine-thread-viewer" target="_blank" rel="noreferrer">gibson9583/engine-thread-viewer</a></p><h3 id="aws-sqs-source-connector" tabindex="-1">AWS SQS Source Connector <a class="header-anchor" href="#aws-sqs-source-connector" aria-label="Permalink to &quot;AWS SQS Source Connector&quot;">​</a></h3><p>Polls AWS SQS queues as a source connector, receiving up to ten messages per long-polling request and delivering each to the channel as a <code>RawMessage</code> with its SQS metadata in the source map. Successfully processed messages are deleted from the queue; failures are left in place and reappear after the visibility timeout.</p><p>Wait time, maximum messages, and visibility timeout are configurable. Authentication supports the default credential chain, static credentials, and STS assume-role. SQS message attributes and FIFO metadata land in the source map, and S3 event notifications are handled in both S3 native and EventBridge formats, with SNS envelopes unwrapped automatically. Every configuration field accepts OIE replacement variables.</p><p><a href="https://github.com/gibson9583/sqs-source-connector" target="_blank" rel="noreferrer">gibson9583/sqs-source-connector</a></p><h2 id="developing-custom-extensions" tabindex="-1">Developing custom extensions <a class="header-anchor" href="#developing-custom-extensions" aria-label="Permalink to &quot;Developing custom extensions&quot;">​</a></h2><p>Server-side extension points are implemented against these types:</p><table tabindex="0"><thead><tr><th>Extension Type</th><th>Class/Interface</th></tr></thead><tbody><tr><td><strong>Server Plugin</strong></td><td><code>ServerPlugin</code> (interface)</td></tr><tr><td><strong>Service Plugin</strong></td><td><code>ServicePlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Channel Plugin</strong></td><td><code>ChannelPlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Data Type</strong></td><td><code>DataTypeServerPlugin</code> (abstract class)</td></tr><tr><td><strong>Resource Plugin</strong></td><td><code>ResourcePlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Library Plugin</strong></td><td><code>LibraryPlugin</code> (interface, extends ResourcePlugin)</td></tr><tr><td><strong>Authorization Plugin</strong></td><td><code>AuthorizationPlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Transmission Mode</strong></td><td><code>TransmissionModeProvider</code> (abstract class, implements ServerPlugin)</td></tr><tr><td><strong>Code Template Plugin</strong></td><td><code>CodeTemplateServerPlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Multi-Factor Auth Plugin</strong></td><td><code>MultiFactorAuthenticationPlugin</code> (abstract class, extends ServicePlugin)</td></tr></tbody></table><p>All ten live in <code>com.mirth.connect.plugins</code>.</p><p>Building an extension means:</p><ol><li>Producing server-side and client-side JARs</li><li>Writing the metadata descriptor (<code>plugin.xml</code>, or <code>source.xml</code> and <code>destination.xml</code> for connectors)</li><li>Packaging it into the extension directory layout</li><li>Testing against a running OIE instance</li></ol><p>To add a browser interface to an extension, the server half stays as it is and you write only the web UI against the REST endpoints the extension already exposes. See <a href="./web_administrator.html">Web Administrator</a> for the extension points available there.</p>`,70)]))}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
